'use strict';

const Dispatcher = require('./dispatcher');
const { kClosed, kDispatch, kCount, kLabel, kOnClose } = require('./symbols');

const KIND = 'kind';

class DispatcherBase extends Dispatcher {
  // Symbol-keyed fields whose keys come from another module.
  [kClosed] = false;

  [kCount] = 0;

  [kOnClose] = null;

  constructor(opts) {
    super();
    this[kLabel] = (opts && opts.label) || 'base';
  }

  get closed() {
    return this[kClosed];
  }

  get dispatched() {
    return this[kCount];
  }

  // A computed accessor name.
  get [KIND]() {
    return 'dispatcher:' + this[kLabel];
  }

  close() {
    if (this[kClosed]) return;
    this[kClosed] = true;
    this.emit('closed', this[kLabel], this[kCount]);
  }

  dispatch(path, handler) {
    if (this[kClosed]) throw new Error(this[kLabel] + ' is closed');
    this[kCount]++;
    // Subclasses declare the symbol-keyed method this calls.
    return this[kDispatch](path, handler);
  }
}

module.exports = DispatcherBase;
